<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Expense Tracker</title>
<style>
  :root {
    --bg: #f4f6f8;
    --card: #ffffff;
    --border: #dde2e8;
    --text: #222;
    --muted: #667;
    --accent: #2f6fed;
    --danger: #d9483f;
  }
  * { box-sizing: border-box; }
  body {
    font-family: -apple-system, "Segoe UI", Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    margin: 0;
    padding: 20px;
  }
  h1 { font-size: 22px; margin: 0 0 16px; }
  .card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 16px;
    margin-bottom: 16px;
    max-width: 720px;
  }
  .row-fields {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    align-items: flex-end;
  }
  .field {
    display: flex;
    flex-direction: column;
    gap: 4px;
    font-size: 13px;
    color: var(--muted);
  }
  input, select, button {
    font-size: 14px;
    padding: 7px 9px;
    border: 1px solid var(--border);
    border-radius: 6px;
    background: #fff;
    color: var(--text);
  }
  #amount { width: 110px; }
  #note { width: 180px; }
  button {
    cursor: pointer;
    background: var(--accent);
    color: #fff;
    border: none;
    font-weight: 600;
  }
  button:hover { opacity: 0.9; }
  #form-error {
    color: var(--danger);
    font-size: 13px;
    margin-top: 8px;
    min-height: 16px;
  }
  .filters {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    align-items: flex-end;
  }
  .summary {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-top: 10px;
  }
  .cat-total {
    background: #eef2fb;
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 5px 10px;
    font-size: 13px;
  }
  #total-line {
    font-size: 16px;
    font-weight: 700;
    margin-top: 10px;
  }
  .list {
    max-width: 720px;
  }
  .expense {
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 10px 12px;
    margin-bottom: 8px;
  }
  .exp-info {
    display: flex;
    gap: 14px;
    align-items: baseline;
    flex-wrap: wrap;
  }
  .exp-amount { font-weight: 700; }
  .exp-category {
    text-transform: capitalize;
    background: #eef2fb;
    padding: 2px 8px;
    border-radius: 10px;
    font-size: 12px;
    color: var(--accent);
  }
  .exp-date { color: var(--muted); font-size: 13px; }
  .exp-note { color: var(--muted); font-size: 13px; font-style: italic; }
  .exp-del {
    background: var(--danger);
    padding: 5px 10px;
    font-size: 12px;
  }
  .empty-msg {
    color: var(--muted);
    font-size: 14px;
    padding: 10px 0;
  }
</style>
</head>
<body>

<h1>Personal Expense Tracker</h1>

<div class="card">
  <div class="row-fields">
    <div class="field">
      <label for="amount">Amount</label>
      <input type="number" id="amount" step="0.01" placeholder="0.00">
    </div>
    <div class="field">
      <label for="category">Category</label>
      <select id="category">
        <option value="groceries">Groceries</option>
        <option value="transport">Transport</option>
        <option value="bills">Bills</option>
        <option value="fun">Fun</option>
      </select>
    </div>
    <div class="field">
      <label for="date">Date</label>
      <input type="date" id="date">
    </div>
    <div class="field">
      <label for="note">Note</label>
      <input type="text" id="note" placeholder="optional">
    </div>
    <div class="field">
      <button id="add-expense" type="button">Add Expense</button>
    </div>
  </div>
  <div id="form-error"></div>
</div>

<div class="card">
  <div class="filters">
    <div class="field">
      <label for="filter-category">Category</label>
      <select id="filter-category">
        <option value="all">All</option>
        <option value="groceries">Groceries</option>
        <option value="transport">Transport</option>
        <option value="bills">Bills</option>
        <option value="fun">Fun</option>
      </select>
    </div>
    <div class="field">
      <label for="filter-from">From</label>
      <input type="date" id="filter-from">
    </div>
    <div class="field">
      <label for="filter-to">To</label>
      <input type="date" id="filter-to">
    </div>
    <div class="field">
      <button id="clear-filters" type="button">Clear Filters</button>
    </div>
  </div>

  <div class="summary" id="summary"></div>
  <div id="total-line">Total: $<span id="total">0.00</span></div>
</div>

<div class="list card" id="list-container">
  <div id="expense-list"></div>
</div>

<script>
(function () {
  var STORAGE_KEY = 'expense-tracker-data';
  var CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];

  var amountEl = document.getElementById('amount');
  var categoryEl = document.getElementById('category');
  var dateEl = document.getElementById('date');
  var noteEl = document.getElementById('note');
  var addBtn = document.getElementById('add-expense');
  var formError = document.getElementById('form-error');

  var filterCategoryEl = document.getElementById('filter-category');
  var filterFromEl = document.getElementById('filter-from');
  var filterToEl = document.getElementById('filter-to');
  var clearFiltersBtn = document.getElementById('clear-filters');

  var listEl = document.getElementById('expense-list');
  var totalEl = document.getElementById('total');
  var summaryEl = document.getElementById('summary');

  function loadExpenses() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed;
    } catch (e) {
      return [];
    }
  }

  function saveExpenses() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
  }

  var expenses = loadExpenses();

  function genId() {
    return 'e' + expenses.length + '-' + Math.floor(Math.random() * 1000000) + '-' + (expenses.length ? expenses[expenses.length - 1].id : '0');
  }

  function addExpense(e) {
    e = e || {};
    var amountStr = amountEl.value;
    var amount = parseFloat(amountStr);
    var date = dateEl.value;

    if (amountStr === '' || isNaN(amount) || amount <= 0) {
      formError.textContent = 'Please enter a valid amount greater than zero.';
      return;
    }
    if (!date) {
      formError.textContent = 'Please select a date.';
      return;
    }

    formError.textContent = '';

    var expense = {
      id: Date.now() + '-' + Math.random().toString(36).slice(2, 8),
      amount: amount,
      category: categoryEl.value,
      date: date,
      note: noteEl.value.trim()
    };

    expenses.push(expense);
    saveExpenses();

    amountEl.value = '';
    noteEl.value = '';

    render();
  }

  function deleteExpense(id) {
    expenses = expenses.filter(function (exp) { return exp.id !== id; });
    saveExpenses();
    render();
  }

  function getFilteredExpenses() {
    var cat = filterCategoryEl.value;
    var from = filterFromEl.value;
    var to = filterToEl.value;

    return expenses.filter(function (exp) {
      if (cat !== 'all' && exp.category !== cat) return false;
      if (from && exp.date < from) return false;
      if (to && exp.date > to) return false;
      return true;
    });
  }

  function formatMoney(n) {
    return n.toFixed(2);
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  function render() {
    var filtered = getFilteredExpenses().slice().sort(function (a, b) {
      if (a.date !== b.date) return a.date < b.date ? 1 : -1;
      return b.id.localeCompare ? b.id.localeCompare(a.id) : 0;
    });

    listEl.innerHTML = '';

    if (filtered.length === 0) {
      var emptyMsg = document.createElement('div');
      emptyMsg.className = 'empty-msg';
      emptyMsg.textContent = 'No expenses to show.';
      listEl.appendChild(emptyMsg);
    } else {
      filtered.forEach(function (exp) {
        var row = document.createElement('div');
        row.className = 'expense';
        row.setAttribute('data-id', exp.id);

        var info = document.createElement('div');
        info.className = 'exp-info';

        var amountSpan = document.createElement('span');
        amountSpan.className = 'exp-amount';
        amountSpan.textContent = '$' + formatMoney(exp.amount);
        info.appendChild(amountSpan);

        var catSpan = document.createElement('span');
        catSpan.className = 'exp-category';
        catSpan.textContent = exp.category;
        info.appendChild(catSpan);

        var dateSpan = document.createElement('span');
        dateSpan.className = 'exp-date';
        dateSpan.textContent = exp.date;
        info.appendChild(dateSpan);

        if (exp.note) {
          var noteSpan = document.createElement('span');
          noteSpan.className = 'exp-note';
          noteSpan.textContent = exp.note;
          info.appendChild(noteSpan);
        }

        row.appendChild(info);

        var delBtn = document.createElement('button');
        delBtn.className = 'exp-del';
        delBtn.type = 'button';
        delBtn.textContent = 'Delete';
        delBtn.addEventListener('click', function () {
          deleteExpense(exp.id);
        });
        row.appendChild(delBtn);

        listEl.appendChild(row);
      });
    }

    var total = filtered.reduce(function (sum, exp) { return sum + exp.amount; }, 0);
    totalEl.textContent = formatMoney(total);

    summaryEl.innerHTML = '';
    CATEGORIES.forEach(function (cat) {
      var catTotal = filtered
        .filter(function (exp) { return exp.category === cat; })
        .reduce(function (sum, exp) { return sum + exp.amount; }, 0);

      var el = document.createElement('div');
      el.className = 'cat-total';
      el.setAttribute('data-cat', cat);
      el.textContent = cat + ': $' + formatMoney(catTotal);
      summaryEl.appendChild(el);
    });
  }

  addBtn.addEventListener('click', function (e) {
    e.preventDefault();
    addExpense();
  });

  amountEl.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      e.preventDefault();
      addExpense();
    }
  });

  filterCategoryEl.addEventListener('change', render);
  filterFromEl.addEventListener('change', render);
  filterToEl.addEventListener('change', render);

  clearFiltersBtn.addEventListener('click', function () {
    filterCategoryEl.value = 'all';
    filterFromEl.value = '';
    filterToEl.value = '';
    render();
  });

  render();
})();
</script>

</body>
</html>
